{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated-run testing is unreported; its occurrence cannot be determined."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "The puzzle count, exact-grid scoring, and narrow intended use are stated. The score describes one run; repeated-run consistency and conditions for fair system comparisons are not documented."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated-run testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Without repeated observations, stability remains unknown; this does not demonstrate instability."
        }
      ],
      "instrument_review": "Exact-grid scoring and a narrow comparison purpose are specified. The documented single-run design leaves score consistency unassessed and limits interpretation of the reported 70%."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations under matching conditions explicitly assessed score variation."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's definition of stability: at most two percentage points."
        }
      ],
      "instrument_review": "Repeated runs support consistency under the specified conditions and stated stability criterion. This supports the narrow puzzle comparison use, but does not establish consistency for other systems, puzzles, or settings."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations explicitly examined variation while holding the listed conditions constant."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's maximum two-percentage-point stability criterion."
        }
      ],
      "instrument_review": "Consistency was tested and failed the stated criterion. The wide reported variation limits using the single 70% score for dependable comparisons; the passage does not explain the variation."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not establish that repeated evaluations occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "No repeated-run findings are supplied to support stability."
        }
      ],
      "instrument_review": "Installation guidance documents setup, but adds no evidence about score consistency. Exact-grid scoring and the narrow purpose are stated; repeated-run performance remains unknown."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated puzzles under the stated scoring and instructions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish a ranking in general intelligence across domains."
        }
      ],
      "instrument_review": "The observed comparison matches the narrow intended use. Fixed instructions and exact-grid scoring provide stated common elements, but other resource controls and repeated-run consistency are unreported. Cross-domain interpretation is unsupported."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported counts support A's better performance on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broad intended use does not supply evidence of performance across domains."
        }
      ],
      "instrument_review": "The stated selection purpose exceeds the evidence's scope. Exact scoring and fixed instructions support interpreting the observed puzzle results, but cross-domain coverage, repeated-run consistency, and other comparison controls are unreported."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial evidence supplies no demonstrated comparison of real workshop decision correctness."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied workshop; the reported difference interval is entirely positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not establish an unmeasured safety benefit."
        }
      ],
      "instrument_review": "Preregistration, random allocation, new cases, blinded correctness checks, and a reported uncertainty interval strengthen the comparison for the stated workshop use. The evidence concerns correctness in one workshop; transfer elsewhere, time effects, and safety benefits remain unestablished."
    }
  ],
  "closing_note": "No instructions were unclear. Missing evidence was distinguished from explicit conflicting evidence."
}
